/**
 * Lazy-loaded per-language learning shards generated by build-open-corpus-index.py
 * into /public/data/learning/{audio,readers,quizzes,freq,grammar}/<langId>.json.
 * Keeps the main JS bundle fast while giving learners access to all ingested data.
 */

export interface AudioShardClip {
  slug: string;
  label: string;
  audioUrl: string;
}

export interface AudioShard {
  languageId: string;
  total: number;
  clips: AudioShardClip[];
}

export interface ReaderStory {
  title: string;
  text: string;
  wordCount?: number;
}

export interface ReaderSentence {
  text: string;
  english?: string;
}

export interface ReaderNewsArticle {
  title: string;
  category: string;
  text: string;
}

export interface ReaderExternalLink {
  title: string;
  url: string;
  source: string;
}

export interface BilingualReadingItem {
  title: string;
  englishTitle?: string;
  text: string;
  english: string;
}

export interface ChapterTranscriptPhrase {
  english: string;
  dholuo: string;
}

export interface ReadersShard {
  languageId: string;
  stories: ReaderStory[];
  bilingualReadings?: BilingualReadingItem[];
  sentences: ReaderSentence[];
  newsArticles: ReaderNewsArticle[];
  externalLinks: ReaderExternalLink[];
  chapterTranscripts?: Record<string, ChapterTranscriptPhrase[]>;
}

export interface QuizQuestionItem {
  type: "reading" | "knowledge" | "science";
  passage?: string;
  subject?: string;
  question: string;
  choices: string[];
  correctIndex: number;
}

export interface QuizzesShard {
  languageId: string;
  total: number;
  questions: QuizQuestionItem[];
}

export interface FreqShard {
  languageId: string;
  total: number;
  words: string[];
}

export interface PhonemeEntry {
  symbol: string;
  allophones?: string;
}

export interface VerbConjugationGroup {
  lemma: string;
  forms: { form: string; label: string }[];
}

export interface GrammarShard {
  languageId: string;
  days: { english: string; local: string }[];
  months: { english: string; local: string }[];
  currencyName?: string | null;
  orthographyLetters: string[];
  familyPath?: string[];
  structureHighlights?: { label: string; detail: string }[];
  phonology: {
    consonants: PhonemeEntry[];
    vowels: PhonemeEntry[];
    tones: PhonemeEntry[];
  };
  conjugations: VerbConjugationGroup[];
}

const shardCache = new Map<string, Promise<unknown>>();

async function fetchShard<T>(kind: string, languageId: string): Promise<T | null> {
  if (typeof window === "undefined" || !languageId) return null;
  const lid = languageId.trim().toLowerCase();
  const key = `${kind}:${lid}`;
  if (!shardCache.has(key)) {
    const p = fetch(`/data/learning/${kind}/${encodeURIComponent(lid)}.json`)
      .then((res) => (res.ok ? res.json() : null))
      .catch(() => null);
    shardCache.set(key, p);
  }
  return (await shardCache.get(key)) as T | null;
}

export function loadAudioShard(languageId: string): Promise<AudioShard | null> {
  return fetchShard<AudioShard>("audio", languageId);
}

export function loadReadersShard(languageId: string): Promise<ReadersShard | null> {
  return fetchShard<ReadersShard>("readers", languageId);
}

export function loadQuizzesShard(languageId: string): Promise<QuizzesShard | null> {
  return fetchShard<QuizzesShard>("quizzes", languageId);
}

export function loadFreqShard(languageId: string): Promise<FreqShard | null> {
  return fetchShard<FreqShard>("freq", languageId);
}

export function loadGrammarShard(languageId: string): Promise<GrammarShard | null> {
  return fetchShard<GrammarShard>("grammar", languageId);
}
